CREATE TABLE IF NOT EXISTS construction_intelligence.project_layouts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_ref uuid NOT NULL UNIQUE, floors jsonb NOT NULL, finish_level varchar(10) NOT NULL DEFAULT 'STANDARD', price_factors jsonb, status varchar(20) NOT NULL DEFAULT 'UNTRUSTED_DATA', source_note varchar(255), confirmed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
